# Created: 2026-09-10

#!/usr/bin/env python3
"""hq-floor: a stdio MCP server that lets Claude Desktop reach a herdr floor.

Dependency free on purpose: Claude Desktop launches this file as a subprocess
(see the `hq-floor` entry it gets in claude_desktop_config.json) and speaks MCP
over newline-delimited JSON-RPC on stdin/stdout. Nothing here needs the `mcp`
package, so it runs on the system python3 and it is testable with a fake
`herdr` on PATH.

Measured premise: the `herdr` CLI answers `workspace list` from a process with
HERDR_ENV, HERDR_PANE_ID, HERDR_TAB_ID and HERDR_WORKSPACE_ID all unset (rc=0).
HERDR_ENV=1 is a policy gate in the herdr skill text, not a socket gate, so a
Desktop-launched subprocess can front the socket.

Surface, deliberately small (a full CLI proxy was considered and rejected):
  floor_status   read   condensed `herdr workspace list` + `herdr agent list`
  floor_read     read   `herdr agent read <name>` recent output
  floor_prompt   write  `herdr agent prompt <target> <text>`, target must pass
                        BOTH the structural name gate and HQ_FLOOR_PROMPT_ALLOW
  floor_inbox    write  one markdown file under ~/.floor/inbox/, the corridor
  floor_notify   write  `herdr notification show`, the doorbell

Never exposed: station open/close, workspace/tab/pane mutation, names --apply,
send-keys, any `pane run`. A Desktop-side compromise gets a mailbox and a
doorbell, not a conductor seat.

House rules enforced on every write: no em dash, en dash or double hyphen in
outbound text (some floors run a hook that rejects them; refuse here so the
failure is named on the Desktop side, not swallowed on the floor).

Env knobs (tests use them):
  HQ_FLOOR_HERDR        binary, default `herdr`
  HQ_FLOOR_DIR          corridor root, default ~/.floor
  HQ_FLOOR_PROMPT_ALLOW comma separated fnmatch globs of promptable agent
                        names, default `*-desk,conductor,conductor-*`
"""

from __future__ import annotations

import datetime as _dt
import fnmatch
import json
import os
import re
import subprocess
import sys
from pathlib import Path

PROTOCOL_VERSION = "2025-06-18"
SERVER_INFO = {"name": "hq-floor", "version": "0.1.0"}

HERDR = os.environ.get("HQ_FLOOR_HERDR", "herdr")
FLOOR_DIR = Path(os.environ.get("HQ_FLOOR_DIR", str(Path.home() / ".floor")))

# The STRUCTURAL gate. Not configurable, on purpose: it is what guarantees that
# no allowlist entry, however loose, can ever admit a flag-shaped or
# shell-shaped value into the herdr argv. HQ_FLOOR_PROMPT_ALLOW can only
# NARROW what this already permits, it can never widen it.
NAME_RE = re.compile(r"^[a-z0-9][a-z0-9-]{0,63}$")

# The POLICY gate, operator configurable. Default: standing desk rows
# (`<slug>-desk`) plus a conductor seat. Both are role names, so a floor that
# names its lanes differently sets HQ_FLOOR_PROMPT_ALLOW instead of patching
# this file. Setting it to `*` is legal and means "any structurally valid agent
# name"; that is the operator's call and it is still gated by NAME_RE.
DEFAULT_PROMPT_ALLOW = "*-desk,conductor,conductor-*"

HAT_RE = re.compile(r"^[a-z][a-z0-9-]{0,31}$")
BAD_DASH_RE = re.compile("\u2014|\u2013|--")  # em dash, en dash, double hyphen, as escapes so this file carries none


def prompt_allow_patterns() -> list[str]:
    raw = os.environ.get("HQ_FLOOR_PROMPT_ALLOW", DEFAULT_PROMPT_ALLOW)
    return [p.strip() for p in raw.split(",") if p.strip()]


TOOLS = [
    {
        "name": "floor_status",
        "description": (
            "Condensed herdr floor state: every workspace with its label and "
            "every live agent with name, status, repo and worktree. Read only."
        ),
        "inputSchema": {
            "type": "object",
            "properties": {},
            "additionalProperties": False,
        },
    },
    {
        "name": "floor_read",
        "description": "Recent terminal output of one live agent, by its unique name. Read only.",
        "inputSchema": {
            "type": "object",
            "properties": {
                "agent": {
                    "type": "string",
                    "description": "live agent name as shown by floor_status",
                },
                "lines": {
                    "type": "integer",
                    "minimum": 10,
                    "maximum": 400,
                    "default": 80,
                },
            },
            "required": ["agent"],
            "additionalProperties": False,
        },
    },
    {
        "name": "floor_prompt",
        "description": (
            "Send a prompt to a floor agent. The target must match the "
            "operator's HQ_FLOOR_PROMPT_ALLOW list. Other targets are refused."
        ),
        "inputSchema": {
            "type": "object",
            "properties": {
                "target": {"type": "string"},
                "text": {"type": "string"},
            },
            "required": ["target", "text"],
            "additionalProperties": False,
        },
    },
    {
        "name": "floor_inbox",
        "description": (
            "Drop a brief into the shared corridor (~/.floor/inbox/) for the "
            "floor to pick up. Returns the file path written."
        ),
        "inputSchema": {
            "type": "object",
            "properties": {
                "hat": {
                    "type": "string",
                    "description": "sender desk slug, e.g. the desk you are sitting at",
                },
                "title": {"type": "string"},
                "body": {
                    "type": "string",
                    "description": "markdown body, drafts and reads only",
                },
            },
            "required": ["hat", "title", "body"],
            "additionalProperties": False,
        },
    },
    {
        "name": "floor_notify",
        "description": "Ring the doorbell: a native herdr notification on the operator's screen.",
        "inputSchema": {
            "type": "object",
            "properties": {
                "title": {"type": "string"},
                "body": {"type": "string", "default": ""},
            },
            "required": ["title"],
            "additionalProperties": False,
        },
    },
]


class ToolError(Exception):
    """Named refusal that surfaces to Desktop as isError=true, never a crash."""


def _herdr(*args: str) -> dict:
    proc = subprocess.run([HERDR, *args], capture_output=True, text=True, timeout=30)
    if proc.returncode != 0:
        raise ToolError(
            f"herdr {' '.join(args[:2])} failed rc={proc.returncode}: {proc.stderr.strip()[:300]}"
        )
    try:
        return json.loads(proc.stdout)
    except json.JSONDecodeError as exc:
        raise ToolError(f"herdr returned non-JSON: {proc.stdout[:200]!r}") from exc


def _lint_text(text: str, field: str) -> None:
    if text.lstrip().startswith("-"):
        raise ToolError(
            f"{field} must not start with a dash; it would be parsed as a herdr flag"
        )
    if BAD_DASH_RE.search(text):
        raise ToolError(
            f"{field} contains an em dash, en dash or double hyphen; the floor refuses those"
        )


def _slug(text: str) -> str:
    s = re.sub(r"[^a-z0-9]+", "-", text.lower()).strip("-")
    return s[:48] or "brief"


def tool_floor_status(_: dict) -> str:
    ws = _herdr("workspace", "list")["result"].get("workspaces", [])
    ag = _herdr("agent", "list")["result"].get("agents", [])
    lines = [f"workspaces {len(ws)} · agents {len(ag)}"]
    for w in ws:
        lines.append(
            f"[{w.get('workspace_id')}] {w.get('label')} · {w.get('agent_status')}"
        )
    for a in ag:
        tok = a.get("tokens", {})
        lines.append(
            f"  {a.get('name') or '(unnamed)'} · {a.get('agent_status')} · "
            f"{tok.get('repo', '?')} · {tok.get('wt', '')} · pane {a.get('pane_id')}"
        )
    return "\n".join(lines)


def tool_floor_read(args: dict) -> str:
    agent = str(args["agent"])
    if not HAT_RE.match(agent):
        raise ToolError("agent must be a live agent name ([a-z][a-z0-9-]{0,31})")
    lines = int(args.get("lines", 80))
    out = _herdr(
        "agent", "read", agent, "--source", "recent-unwrapped", "--lines", str(lines)
    )
    res = out.get("result", {})
    return res.get("text") or json.dumps(res)[:4000]


def tool_floor_prompt(args: dict) -> str:
    target = str(args["target"])
    text = str(args["text"])
    patterns = prompt_allow_patterns()
    if not NAME_RE.match(target):
        raise ToolError(
            f"target {target!r} refused: not a structurally valid agent name "
            "([a-z0-9][a-z0-9-]{0,63})"
        )
    if not any(fnmatch.fnmatchcase(target, pat) for pat in patterns):
        raise ToolError(
            f"target {target!r} refused: no HQ_FLOOR_PROMPT_ALLOW pattern matches it "
            f"(allow list: {', '.join(patterns) or '(empty)'})"
        )
    _lint_text(text, "text")
    out = _herdr("agent", "prompt", target, text)
    return json.dumps(out.get("result", out))[:1000]


def tool_floor_inbox(args: dict) -> str:
    hat = str(args["hat"])
    if not HAT_RE.match(hat):
        raise ToolError("hat must be a desk slug ([a-z][a-z0-9-]{0,31})")
    title, body = str(args["title"]), str(args["body"])
    _lint_text(title, "title")
    _lint_text(body, "body")
    inbox = FLOOR_DIR / "inbox"
    inbox.mkdir(parents=True, exist_ok=True)
    stamp = _dt.datetime.now().strftime("%Y-%m-%d-%H%M")
    path = inbox / f"{stamp}-{hat}-{_slug(title)}.md"
    path.write_text(
        f"# {title}\n\nfrom: {hat}-desk (Claude Desktop) · {stamp}\n\n{body.rstrip()}\n",
        encoding="utf-8",
    )
    return str(path)


def tool_floor_notify(args: dict) -> str:
    title = str(args["title"])
    body = str(args.get("body", ""))
    _lint_text(title, "title")
    if body:
        _lint_text(body, "body")
    cmd = ["notification", "show", title]
    if body:
        cmd.append(f"--body={body}")
    _herdr(*cmd)
    return "shown"


HANDLERS = {
    "floor_status": tool_floor_status,
    "floor_read": tool_floor_read,
    "floor_prompt": tool_floor_prompt,
    "floor_inbox": tool_floor_inbox,
    "floor_notify": tool_floor_notify,
}


def handle(msg: dict) -> dict | None:
    """Return a JSON-RPC response for a request, or None for a notification."""
    method = msg.get("method")
    mid = msg.get("id")
    if mid is None:
        return None  # notifications/initialized and friends
    if method == "initialize":
        return _ok(
            mid,
            {
                "protocolVersion": PROTOCOL_VERSION,
                "capabilities": {"tools": {}},
                "serverInfo": SERVER_INFO,
            },
        )
    if method == "ping":
        return _ok(mid, {})
    if method == "tools/list":
        return _ok(mid, {"tools": TOOLS})
    if method == "tools/call":
        params = msg.get("params") or {}
        name = str(params.get("name") or "")
        fn = HANDLERS.get(name)
        if fn is None:
            return _err(mid, -32602, f"unknown tool {name!r}")
        try:
            text = fn(params.get("arguments") or {})
            return _ok(
                mid, {"content": [{"type": "text", "text": text}], "isError": False}
            )
        except ToolError as exc:
            return _ok(
                mid,
                {
                    "content": [{"type": "text", "text": f"REFUSED: {exc}"}],
                    "isError": True,
                },
            )
        except (subprocess.TimeoutExpired, OSError, KeyError, ValueError) as exc:
            return _ok(
                mid,
                {
                    "content": [{"type": "text", "text": f"FAILED: {exc}"}],
                    "isError": True,
                },
            )
    return _err(mid, -32601, f"method not found: {method}")


def _ok(mid, result) -> dict:
    return {"jsonrpc": "2.0", "id": mid, "result": result}


def _err(mid, code, message) -> dict:
    return {"jsonrpc": "2.0", "id": mid, "error": {"code": code, "message": message}}


def main() -> int:
    for raw in sys.stdin:
        raw = raw.strip()
        if not raw:
            continue
        try:
            msg = json.loads(raw)
        except json.JSONDecodeError:
            continue
        resp = handle(msg)
        if resp is not None:
            sys.stdout.write(json.dumps(resp) + "\n")
            sys.stdout.flush()
    return 0


if __name__ == "__main__":
    sys.exit(main())
